+func TestLowerBound(t *testing.T) {
+	tests := []struct {
+		name  string
+		value int
+		low   int
+		high  int
+	}{
+		{name: "below", value: 0, low: 1, high: 9},
+		{name: "at", value: 1, low: 1, high: 9},
+		{name: "single value interval", value: 1, low: 1, high: 1},
+	}
